import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";

const contentDirectory = resolve(process.cwd(), "content/editorial");
const outputPath = resolve(process.cwd(), "app/modules/editorial/editorial.bundled.ts");

const entries = readdirSync(contentDirectory)
  .filter((fileName) => fileName.endsWith(".md") || fileName.endsWith(".mdx"))
  .sort()
  .map((fileName) => {
    const filePath = join(contentDirectory, fileName);
    const source = readFileSync(filePath, "utf8");
    const closingDelimiter = source.indexOf("\n---\n", 4);
    if (!source.startsWith("---\n") || closingDelimiter === -1) {
      throw new Error(`${fileName}: editorial content must use JSON frontmatter.`);
    }
    const frontmatter = JSON.parse(source.slice(4, closingDelimiter).trim());
    return {
      frontmatter: {
        relatedIds: [],
        sources: [],
        disclosures: [],
        ...frontmatter,
      },
      body: source.slice(closingDelimiter + 5).trim(),
      filePath: `bundled:${fileName}`,
    };
  });

const generated = `// Generated by scripts/build-editorial-bundle.mjs. Do not edit by hand.\nimport type { EditorialEntry } from "./editorial.types";\n\nexport const bundledEditorialEntries = ${JSON.stringify(entries, null, 2)} satisfies readonly EditorialEntry[];\n`;
writeFileSync(outputPath, generated);
